using System.Collections;
using Axiom.Gameplay;
using Axiom.Gameplay.SceneManagement;
using Object=Axiom.Gameplay.Object;
namespace Game;
public struct SaveStructProbe {public int count;}
public sealed class SaveProbe {public int count=2;public Vector3 position=new(1,2,3);public string label="Save";}
public sealed class RuntimeBatchProbe : MonoBehaviour {
 [ReadOnly] public int Created=0;
 public Transform? Target;public LinkedBehaviour? Other;public TextAsset? Settings;
 [ReadOnly] public int Checks=0;[ReadOnly] public int Frames=0;[ReadOnly] public bool AsyncReady=false;
 private void Check(bool value,string message){if(!value)throw new System.Exception(message);Checks++;}
 private IEnumerator Ready(){yield return new AsyncOperation();AsyncReady=true;}
 public override void Start(){StartCoroutine(Ready());
  Check(Target!=null&&Target.gameObject.name=="Root"&&Other!=null&&Other.Value==7&&Settings!=null&&Settings.text.Contains("difficulty"),"typed references resolved before Start");
  Check(Application.isPlaying&&Application.isEditor&&Screen.width>0&&Screen.height>0,"platform metadata");
  var jsonSave=JsonUtility.ToJson(new SaveProbe());var restored=JsonUtility.FromJson<SaveProbe>(jsonSave);Check(JsonUtility.FromJson<SaveStructProbe>("{\"count\":9}").count==9,"JSON struct values are populated");Check(restored.count==2&&restored.position==new Vector3(1,2,3)&&restored.label=="Save","JSON public fields and vectors");
  var camera=GetComponent<Camera>()!;camera.fieldOfView=55;camera.orthographic=true;camera.orthographicSize=4;Check(camera.fieldOfView==55&&camera.orthographic&&camera.orthographicSize==4,"live camera facade");camera.orthographic=false;
  Axiom.Gameplay.AI.NavMesh.BuildGrid(Vector3.zero,4,3,1,new[]{1});var route=new Axiom.Gameplay.AI.NavMeshPath();Check(Axiom.Gameplay.AI.NavMesh.CalculatePath(new Vector3(.5,0,.5),new Vector3(3.5,0,.5),-1,route)&&route.status==Axiom.Gameplay.AI.NavMeshPathStatus.PathComplete&&route.corners.Length>4,"A star obstacle detour");Check(Axiom.Gameplay.AI.NavMesh.SamplePosition(new Vector3(1.5,0,.5),out var sample,1.1,-1)&&sample.hit,"navigation sample");var agent=gameObject.AddComponent<Axiom.Gameplay.AI.NavMeshAgent>();Check(GetComponent<Axiom.Gameplay.AI.NavMeshAgent>()==agent&&agent.SetDestination(new Vector3(3.5,0,.5)),"agent component and destination");Object.Destroy(agent);
  var request=Axiom.Gameplay.Networking.UnityWebRequest.Get("https://example.test/data");var asyncRequest=request.SendWebRequest();Check(!asyncRequest.isDone&&request.result==Axiom.Gameplay.Networking.UnityWebRequest.Result.InProgress,"async request queued");request.Abort();Check(asyncRequest.isDone&&request.error!=null,"async request cancellation");
  Check(Resources.LoadAsync<TextAsset>("Assets/Settings.json").isDone,"resource async facade");
  Check(PlayerPrefs.GetInt("score")==7,"loaded project preference");PlayerPrefs.SetInt("score",8);PlayerPrefs.SetString("name","Player");PlayerPrefs.Save();
  Check(Resources.Load<TextAsset>("Assets/Settings.json")!.text.Contains("difficulty"),"text asset");Check(Resources.Load<TextAsset>("missing")==null,"missing resource");
  var clone=Object.Instantiate(Resources.Load<PrefabAsset>("Assets/Test.prefab.json")!);Check(clone.name=="Prefab cube (clone)","resource clone name");Check(clone.transform.childCount==1,"resource hierarchy");Object.Destroy(clone);
  var original=SceneManager.GetActiveScene();var empty=SceneManager.CreateScene("Temporary");Check(SceneManager.SetActiveScene(empty),"set active scene");var marker=new GameObject("Marker");Check(empty.GetRootGameObjects().Any(g=>g.name=="Marker"),"scene ownership");SceneManager.MoveGameObjectToScene(marker,original);Check(!empty.GetRootGameObjects().Any(g=>g.name=="Marker"),"move scene ownership");SceneManager.SetActiveScene(original);SceneManager.UnloadSceneAsync("Temporary");Check(SceneManager.sceneCount==1,"unload empty scene");
  SceneManager.LoadScene("Arena",LoadSceneMode.Additive);Check(SceneManager.sceneCount==2&&GameObject.Find("Arena cube")!=null,"additive load");SceneManager.UnloadSceneAsync("Arena");Check(GameObject.Find("Arena cube")==null,"unload objects");Object.DontDestroyOnLoad(gameObject);SceneManager.LoadScene(0);Check(gameObject.name=="Root"&&GameObject.Find("Arena cube")!=null&&SceneManager.sceneCount==1,"single load preserves marked root");
  var body=gameObject.GetComponent<Rigidbody>()!;body.linearDamping=2;body.angularDamping=3;body.constraints=RigidbodyConstraints.FreezePositionX|RigidbodyConstraints.FreezeRotationY;Check(body.drag==2&&body.angularDrag==3&&body.constraints.HasFlag(RigidbodyConstraints.FreezePositionX),"damping constraints");body.collisionDetectionMode=CollisionDetectionMode.Continuous;Check(body.collisionDetectionMode==CollisionDetectionMode.Continuous,"continuous");body.Sleep();Check(body.IsSleeping(),"sleep");body.AddForce(Vector3.up,ForceMode.Impulse);Check(!body.IsSleeping(),"force wakes");
  var two=new GameObject("Body2D");var c=two.AddComponent<BoxCollider2D>();var b=two.AddComponent<Rigidbody2D>();b.velocity=Vector2.right;b.angularVelocity=90;b.bodyType=RigidbodyType2D.Static;b.velocity=Vector2.right;b.angularVelocity=90;Check(b.velocity==Vector2.zero&&b.angularVelocity==0,"static bodies clear and reject momentum");Check(b.bodyType==RigidbodyType2D.Static,"static 2d");b.bodyType=RigidbodyType2D.Kinematic;b.velocity=new Vector2(1,0);Check(b.isKinematic,"kinematic 2d");b.constraints=RigidbodyConstraints2D.FreezePositionY|RigidbodyConstraints2D.FreezeRotation;Check(b.constraints.HasFlag(RigidbodyConstraints2D.FreezeRotation),"2d constraints");b.simulated=false;Check(!b.simulated&&Physics2D.OverlapCircle(new Vector2(0,0),10)==null,"unsimulated query");b.simulated=true;
  Physics.gravity=new Vector3(0,-5,0);Physics2D.gravity=new Vector2(0,-3);Physics.IgnoreLayerCollision(1,2);Check(Physics.gravity.Y==-5&&Physics2D.gravity.Y==-3&&Physics.GetIgnoreLayerCollision(2,1),"global settings");Physics.IgnoreCollision(gameObject.GetComponent<Collider>()!,c);Check(Physics.GetIgnoreCollision(c,gameObject.GetComponent<Collider>()!),"pair filter");
  var arena=GameObject.Find("Arena cube")!;var target=arena.AddComponent<BoxCollider>();arena.transform.position=new Vector3(8,0,0);Check(Physics.SphereCast(new Vector3(5,0,0),.5,Vector3.right,out var hit,10)&&System.Math.Abs(hit.distance-2)<.001,"sphere cast against box");Check(Physics.BoxCast(new Vector3(5,0,0),new Vector3(.5,.5,.5),Vector3.right,out hit,Quaternion.identity,10)&&System.Math.Abs(hit.distance-2)<.001,"swept SAT box cast");Check(Physics2D.CircleCast(new Vector2(-3,0),.5,Vector2.right,10).collider!=null,"circle cast");var filter=new ContactFilter2D().NoFilter();two.layer=4;filter.SetLayerMask(1<<4);filter.SetDepth(-1,1);Check(Physics2D.OverlapCircle(Vector2.zero,10,filter,new Collider2D[4])==1,"contact filter");
  Input.RebindButton("Interact","KeyE","Gamepad0/Button1");Input.RebindAxis("Climb","KeyQ","KeyE");Input.RebindGamepadAxis("Steer",0,0,-1,.1);var json=Input.SaveBindingOverridesAsJson();Input.LoadBindingOverridesFromJson(json);PlayerPrefs.SetString("bindings",json);PlayerPrefs.Save();
 }
 public override void Update(){Frames++;for(var i=0;i<33;i++){var temporary=new GameObject("Transient");temporary.transform.SetParent(transform);Object.Destroy(temporary);Created++;}Check(transform.childCount==0,"destroyed children leave no hierarchy ghosts");if(Frames==1){var graph=new GameObject("Graph root");var child=new GameObject("Graph child");child.transform.SetParent(graph.transform);var graphScript=graph.AddComponent<ReferenceGraphProbe>();var childScript=child.AddComponent<ReferenceGraphProbe>();graphScript.Peer=child;childScript.Peer=graph;var graphClone=Object.Instantiate(graph);var cloneChild=graphClone.transform.GetChild(0).gameObject;Check(graphClone.GetComponent<ReferenceGraphProbe>()!.Peer!.GetInstanceID()==cloneChild.GetInstanceID(),"clone reference remaps root to child");Check(cloneChild.GetComponent<ReferenceGraphProbe>()!.Peer!.GetInstanceID()==graphClone.GetInstanceID(),"clone reference remaps child to root");Object.Destroy(graph);Object.Destroy(graphClone);Check(Input.GetKeyDown(KeyCode.E)&&Input.GetKey(KeyCode.F1),"expanded keys");Check(Input.GetButtonDown("Interact")&&Input.GetAxisRaw("Climb")==1,"remapped actions");Check(Input.GetAxisRaw("Mouse X")==3&&Input.GetAxisRaw("Mouse Y")==-2,"generic mouse axes");Check(Input.GetMouseButtonDown(0)&&Input.mousePosition.X==120&&Input.mouseScrollDelta.Y==2,"mouse snapshot");Check(Input.GetJoystickNames().Length==1&&Input.GetGamepadAxis(0,0)>.8&&Input.GetGamepadButton(0,1)&&Input.GetGamepadButtonDown(0,1)&&Input.GetAxisRaw("Steer")<-.8,"gamepad snapshot");Check(Input.touchCount==1&&Input.GetTouch(0).phase==TouchPhase.Began,"touch began");}else if(Frames==2){Check(AsyncReady,"completed resource operation can be yielded");Check(Input.GetKeyUp(KeyCode.E)&&Input.GetButtonUp("Interact"),"released action");Check(Input.GetMouseButtonUp(0)&&Input.GetTouch(0).phase==TouchPhase.Ended,"mouse touch release");}}
}
